172			return
173		}
174		after, limit := int64(0), 100
175		for key, values := range query {
176			if len(values) != 1 {
177				writeError(w, http.StatusBadRequest, "invalid_request")
178				return
179			}
180			switch key {
181			case "after":
182				v, ok := parseAuditInt(values[0])
183				if !ok {
184					writeError(w, http.StatusBadRequest, "invalid_request")
185					return
186				}
187				after = v
188			case "limit":
189				v, ok := parseAuditInt(values[0])
190				if !ok || v < 1 || v > 1000 {
191					writeError(w, http.StatusBadRequest, "invalid_request")
192					return
193				}
194				limit = int(v)
195			default:
196				writeError(w, http.StatusBadRequest, "invalid_request")
197				return
198			}
199		}
200		events, hasMore, expired := a.snapshot(after, limit)
201		if expired {
202			writeError(w, http.StatusGone, "audit_cursor_expired")
203			return
204		}
205		nextAfter := after
206		if len(events) > 0 {
207			nextAfter = events[len(events)-1].Seq
208		}
209		writeJSON(w, http.StatusOK, auditResponse{
210			Events:    events,
211			NextAfter: nextAfter,
212			HasMore:   hasMore,
213		})
214	}
215	
216	// parseAuditInt parses a non-negative decimal integer with no sign or other
217	// decoration; anything else, including values beyond int64 range, is
218	// rejected.
219	func parseAuditInt(s string) (int64, bool) {
220		if s == "" {
221			return 0, false
222		}
223		for _, c := range s {
224			if c < '0' || c > '9' {
225				return 0, false
226			}
227		}
228		v, err := strconv.ParseInt(s, 10, 64)
229		if err != nil {
230			return 0, false
231		}
232		return v, true
233	}
