		contentType = nil
	} else {
		var s string
		if err := json.Unmarshal(*doc.ContentType, &s); err != nil {
			return invalid()
		}
		contentType = &s
	}

	if contentType != nil && !validContentTypeValue(*contentType) {
		return badValue()
	}
	if len(*doc.Labels) > maxLabels {
		return badValue()
	}
	for key, value := range *doc.Labels {
		if !validLabelKey(key) || !validLabelValue(value) {
			return badValue()
		}
	}
	return expected, contentType, *doc.Labels, "", 0
